package docs

import "github.com/alternayte/gx"

// kindClass maps a callout tone to its accent classes (REQ-STY-05).
var kindClass = gx.Enum[Kind]{
	Note:    "",
	Tip:     "gx-aside-tip",
	Caution: "gx-aside-caution",
	Danger:  "gx-aside-danger",
}

// Kind is the tone of a docs callout (REQ-CNT-05).
type Kind string

// The tones of docs.Aside.
const (
	Note    Kind = "note"
	Tip     Kind = "tip"
	Caution Kind = "caution"
	Danger  Kind = "danger"
)

package docs

import "github.com/alternayte/gx"

// badgeClass maps a badge variant to its classes (REQ-STY-05).
var badgeClass = gx.Enum[BadgeVariant]{
	BadgeDefault:     "border-transparent bg-primary text-primary-foreground",
	BadgeSecondary:   "border-transparent bg-secondary text-secondary-foreground",
	BadgeDestructive: "border-transparent bg-destructive text-white",
	BadgeOutline:     "text-foreground",
}

// BadgeVariant is the visual style of a docs badge (REQ-CNT-05).
type BadgeVariant string

// The variants of docs.Badge.
const (
	BadgeDefault     BadgeVariant = "default"
	BadgeSecondary   BadgeVariant = "secondary"
	BadgeDestructive BadgeVariant = "destructive"
	BadgeOutline     BadgeVariant = "outline"
)

package docs

// FileTreeItem is one file or directory of docs.FileTree (REQ-CNT-05).
type FileTreeItem struct {
	// Name is the shown base name.
	Name string
	// Dir marks a directory.
	Dir bool
	// Comment adds a short note after the name.
	Comment string
	// Children holds the directory entries.
	Children []FileTreeItem
}

package docs

import "github.com/alternayte/gx"

// buttonClass maps a link-button variant to its classes (REQ-STY-05).
var buttonClass = gx.Enum[ButtonVariant]{
	ButtonPrimary:   "bg-primary text-primary-foreground hover:bg-primary/90",
	ButtonSecondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
	ButtonOutline:   "border border-border bg-transparent hover:bg-accent",
	ButtonGhost:     "bg-transparent hover:bg-accent",
}

// ButtonVariant is the visual style of a docs link button (REQ-CNT-05).
type ButtonVariant string

// The variants of docs.LinkButton.
const (
	ButtonPrimary   ButtonVariant = "primary"
	ButtonSecondary ButtonVariant = "secondary"
	ButtonOutline   ButtonVariant = "outline"
	ButtonGhost     ButtonVariant = "ghost"
)
